	@ParameterizedTest
	@EnumSource(Route.class)
	void theFirstDistinctKeyPaysForTheOrdinaryProducerRowsAlreadyPrefetched(Route route) throws Exception {
		// measureSlice proves sixteen positive root/tail matches for either IR tier, but only one
		// root/tail match for nested-loop. The full control has the same sixteen physical matches.
		LmdbNativeCostVector full = measure(route, true);
		LmdbNativeCostVector sliced = measureSlice(route, 0L);
		Feature traversal = route == Route.COMPILED ? Feature.GENERATED_ROW : Feature.INTERPRETED_ROW;
		double consumedFraction = route == Route.NESTED ? 1D / ROWS : 1D;
		assertThat(full.expected(traversal)).as("the selected tier's positive producer work").isPositive();
		assertThat(sliced.expected(Feature.DISTINCT_UPDATE))
				.as("the serial root sees only its first consumed key, not the prefetched tail")
				.isEqualTo(1D);
		assertThat(sliced.expected(Feature.OUTPUT_MATERIALIZATION))
				.as("only the first returned BindingSet is allocated")
				.isEqualTo(1D);
		assertThat(sliced.expected(traversal))
				.as("ordinary IR fills its complete sixteen-row buffer; nested-loop pulls only one match")
				.isEqualTo(full.expected(traversal) * consumedFraction);
		assertThat(sliced.expected(Feature.SCANNED_ROW))
				.as("both physical pattern records are read for every prefetched positive match")
				.isEqualTo(full.expected(Feature.SCANNED_ROW) * consumedFraction);
	}

